#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# Chain 31 rollout wizard (#41 steps 1 to 5), from the checked runbooks:
# docs/development/deploy.md ("Chain 31 rollout"), docs/demo.md, docs/runbooks/outage.md
# sections 7 and 8, rotation.md and compromise.md. It fills in the drill log template
# (docs/runbooks/drill-log.md) and writes it to $ROLLOUT_DIR/drill-log.md.
#
#   contracts/script/rollout-wizard.sh            run or resume the rollout
#   contracts/script/rollout-wizard.sh --status   list the stages and which are done
#
# Progress and every captured value live in $ROLLOUT_DIR/state.env (default .rollout-31/
# at the repository root, ignored by git). Rerun the wizard to resume where it stopped.
#
# The wizard never reads, stores or asks for key material. Signing stays on the Ledger
# and in the Safe UI. The demo scripts need DEMO_PRIVATE_KEY, so you run them in a second
# shell and the wizard reads their output files. It refuses to start if a private key is
# set in its own environment, and it refuses any answer that looks like key material.
# Transactions are pasted as explorer links, never as bare 32-byte hex, so a private key
# pasted by mistake is refused before anything is sent to an RPC.

REPO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
ROLLOUT_DIR=${ROLLOUT_DIR:-$REPO_ROOT/.rollout-31}
ENV_FILE="$ROLLOUT_DIR/state.env"
RECORD=${RECORD:-deployments/31.json}
DRILL_LOG="$ROLLOUT_DIR/drill-log.md"
EXPLORER=https://rootstock-testnet.blockscout.com
SAFE_UI=https://safe.rootstock.io
PUBLIC_RPC=https://public-node.testnet.rsk.co
SAFE_L2_SINGLETON=0x00000000000000000000000029fcb43b46531bca003ddc8fcb67ffe91900c762
# keccak256("RandomnessRequested(bytes32,address,bytes32,uint32,uint64,uint48,uint48,uint96,uint32)")
REQUESTED_TOPIC=0x548fbfced1f0370ecbb6d0a49365208f8b1711725efcadc9d1650ecc6be3e377
DEMO_SCRIPTS=(dice read-path reverting-consumer withdraw-fees recompute-beta rejections)
GRACE_BLOCKS=100
RETIRE_BLOCKS=2400

# Stage ids, in the order of #41. Progress is DONE_<id> in state.env.
STEP_IDS=(rpc safe deploy verify handoff check discard commit gate drill-header failover rotation revocation outage missed final publish)
STEP_TITLES=(
  "Step 1: RPC of chain 31"
  "Step 1: create the Admin Safe"
  "Step 1: deploy"
  "Step 1: verify on Blockscout and Sourcify"
  "Step 1: hand off to the Admin Safe"
  "Step 1: run the deployment check"
  "Step 1: discard the deployer key"
  "Step 1: commit the deployment record"
  "Step 2: gate, the demo scripts on chain 31"
  "Step 3: drill log header"
  "Step 3: drill, failover to the Backup Worker"
  "Step 3: drill, Rotation with a request pending"
  "Step 3: drill, Revocation with a request pending and its refund"
  "Step 4: outage window"
  "Step 4: count the missed Deadlines"
  "Step 5: final demo run"
  "Step 5: write the drill log"
)

# ── Key material ──────────────────────────────────────────────────────────

# refuse_key_env stops before anything runs if a private key or mnemonic is set in this
# shell. It only tests that the variable is set: it never prints the value.
refuse_key_env() {
  local name found=()
  for name in $(compgen -e); do
    case "$name" in
      *PRIVATE_KEY*|*MNEMONIC*|*SEED_PHRASE*|ETH_KEYSTORE_PASSWORD) [[ -n "${!name:-}" ]] && found+=("$name") ;;
    esac
  done
  (( ${#found[@]} )) || return 0
  printf '%s is set in this shell.\n' "${found[@]}" >&2
  printf 'The rollout wizard never holds key material. Unset it here (unset %s). Set\n' "${found[*]}" >&2
  printf 'DEMO_PRIVATE_KEY only in the second shell where you run the demo scripts.\n' >&2
  exit 1
}

# looks_like_key VALUE: bare 32-byte hex, a mnemonic, an extended private key, a PEM key
# or a keystore.
looks_like_key() {
  local v="$1"
  [[ "$v" =~ ^(0x)?[0-9a-fA-F]{64}$ ]] && return 0
  [[ "$v" =~ ^[a-z]+([[:space:]]+[a-z]+){11,}$ ]] && return 0
  [[ "$v" =~ ^[xtyz]prv ]] && return 0
  [[ "$v" == *"PRIVATE KEY"* || "$v" == *ciphertext* || "$v" == \{* ]] && return 0
  return 1
}

refused() {
  warn "That looks like key material. It was not saved and not sent anywhere."
  note "The wizard does not take keys. Signing stays on the Ledger and in the Safe UI."
}

# ── State ─────────────────────────────────────────────────────────────────

utc_time()  { date -u +%H:%M:%S; }
utc_stamp() { date -u +%Y-%m-%dT%H:%M:%SZ; }
state()     { _existing "$1" || true; }
put()       { write_env "$1" "$2" >/dev/null; }
is_done()   { [[ -n "$(state "DONE_${1//-/_}")" ]]; }

# load_state sets a shell variable for each value saved by an earlier run.
load_state() {
  [[ -f "$ENV_FILE" ]] || return 0
  local key
  while IFS= read -r key; do
    printf -v "$key" '%s' "$(state "$key")"
  done < <(grep -oE '^[A-Za-z_][A-Za-z0-9_]*=' "$ENV_FILE" | tr -d '=' | sort -u)
}

# hold "msg" waits for Enter, and stops the wizard (to be resumed) if input has ended.
hold() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || { printf '\n'; warn "No more input. Stopped; rerun the wizard to resume here."; exit 1; }
}

# run_step ID FN runs one stage, unless an earlier run finished it.
run_step() {
  local id="$1" fn="$2" i title=""
  for i in "${!STEP_IDS[@]}"; do [[ "${STEP_IDS[$i]}" == "$id" ]] && title="${STEP_TITLES[$i]}"; done
  if is_done "$id"; then _STAGE_INDEX=$((_STAGE_INDEX + 1)); return 0; fi
  stage "$title"
  put "STAGE_${id//-/_}_START_AT" "$(utc_stamp)"
  "$fn"
  put "DONE_${id//-/_}" "$(utc_stamp)"
}

print_status() {
  local i next=""
  for i in "${!STEP_IDS[@]}"; do
    if is_done "${STEP_IDS[$i]}"; then
      printf 'done  %-13s %s\n' "${STEP_IDS[$i]}" "${STEP_TITLES[$i]}"
    else
      printf 'todo  %-13s %s\n' "${STEP_IDS[$i]}" "${STEP_TITLES[$i]}"
      [[ -n "$next" ]] || next="${STEP_IDS[$i]}"
    fi
  done
  printf 'next: %s\n' "${next:-none}"
}

# ── Questions ─────────────────────────────────────────────────────────────

# ask_public KEY "Prompt" [VALIDATOR] asks for a public value until it is not key
# material and VALIDATOR accepts it, then saves it.
ask_public() {
  local key="$1" prompt="$2" check="${3:-}"
  while :; do
    ask "$key" "$prompt" || { warn "No more input. Stopped; rerun the wizard to resume here."; exit 1; }
    if looks_like_key "${!key}"; then printf -v "$key" '%s' ''; refused; continue; fi
    if [[ -n "$check" ]] && ! "$check" "${!key}"; then printf -v "$key" '%s' ''; continue; fi
    break
  done
  put "$key" "${!key}"
}

# ask_default KEY "Prompt" DEFAULT: like ask_public; Enter gives DEFAULT.
ask_default() {
  local key="$1" prompt="$2" default="$3"
  while :; do
    ask "$key" "$prompt [Enter: $default]" || { warn "No more input. Stopped; rerun the wizard to resume here."; exit 1; }
    [[ -n "${!key}" ]] || printf -v "$key" '%s' "$default"
    if looks_like_key "${!key}"; then printf -v "$key" '%s' ''; refused; continue; fi
    break
  done
  put "$key" "${!key}"
}

is_address() { [[ "$1" =~ ^0x[0-9a-fA-F]{40}$ ]] || { warn "Not an address (0x and 40 hex digits)."; return 1; }; }
is_link()    { [[ "$1" =~ ^https?://[^[:space:]]+$ ]] || { warn "Not a link (https://...)."; return 1; }; }
is_text()    { [[ -n "$1" ]] || { warn "Write something."; return 1; }; }
is_uint()    { [[ "$1" =~ ^[0-9]+$ ]] || { warn "Not a whole number."; return 1; }; }

# on_curve X Y: the point is on secp256k1. A secret scalar is never a valid pair.
on_curve() {
  python3 -c 'import sys
p = 2**256 - 2**32 - 977
x, y = int(sys.argv[1]), int(sys.argv[2])
sys.exit(0 if 0 < x < p and 0 < y < p and (y * y - x * x * x - 7) % p == 0 else 1)' "$1" "$2"
}

# ask_point PREFIX "what": a Proving Key's public point, into PREFIX_X and PREFIX_Y.
ask_point() {
  local px="${1}_X" py="${1}_Y"
  while :; do
    ask_public "$px" "x of the public point of $2 (decimal):" is_uint
    ask_public "$py" "y of the public point of $2 (decimal):" is_uint
    on_curve "${!px}" "${!py}" && return 0
    warn "That is not a point on secp256k1. Copy x and y of the public point from the keygen output."
    put "$px" ''; put "$py" ''
  done
}

# receipt_field HASH FIELD
receipt_field() { cast receipt --rpc-url "$RPC_URL" "$1" "$2" 2>/dev/null; }

tx_link() { printf '%s/tx/%s' "$EXPLORER" "$1"; }

# ask_tx KEY "Prompt": the explorer link of a transaction. A bare hash is refused (it has
# the shape of a private key). The hash is saved as KEY, with KEY_BLOCK, only after the
# chain shows a receipt for it.
ask_tx() {
  local key="$1" prompt="$2" input status hash
  while :; do
    ask "$key" "$prompt ($EXPLORER/tx/...)" || { warn "No more input. Stopped; rerun the wizard to resume here."; exit 1; }
    input="${!key}"; printf -v "$key" '%s' ''
    if looks_like_key "$input"; then refused; note "Paste the explorer link of the transaction, not the bare hash."; continue; fi
    if [[ "$input" =~ ^$EXPLORER/tx/(0x[0-9a-fA-F]{64})/?$ ]]; then
      hash="${BASH_REMATCH[1]}"
    elif [[ "$input" =~ ^0x[0-9a-fA-F]{64}$ ]]; then
      hash="$input"   # the saved value from an earlier run (Enter keeps it)
    else
      warn "Not a transaction link ($EXPLORER/tx/0x...)."; continue
    fi
    if ! status=$(receipt_field "$hash" status); then
      warn "No transaction $hash on chain 31. It was not saved."
      continue
    fi
    if ! [[ "$status" =~ ^(1|0x1)([^0-9a-fA-F]|$) ]]; then
      warn "That transaction reverted (status $status)."
      confirm "Save it anyway, as a reverted transaction?" || continue
    fi
    printf -v "$key" '%s' "$hash"
    put "$key" "$hash"
    put "${key}_BLOCK" "$(receipt_field "$hash" blockNumber)"
    return 0
  done
}

# ── Chain reads (no keys) ─────────────────────────────────────────────────

block_now() { cast block-number --rpc-url "$RPC_URL"; }

# blocks_between FROM TO: TO - FROM, or empty if either is missing.
blocks_between() { [[ "$1" =~ ^[0-9]+$ && "$2" =~ ^[0-9]+$ ]] && printf '%s' "$(( $2 - $1 ))" || true; }

# word HEX INDEX: the INDEX-th 32-byte word of ABI-encoded HEX, without 0x.
word() { local h="${1#0x}"; printf '%s' "${h:$((64 * $2)):64}"; }
# word_dec HEX INDEX: that word as a decimal number (small values only).
word_dec() { local w; w=$(word "$1" "$2" | sed 's/^0*//'); printf '%d' "$((16#${w:-0}))"; }

# getRequest fields: requester, status, callbackGasCap, requestBlock, drandConfigId, fee,
# targetRound, deadline, confirmations, keyId, ...
REQUEST_STATUS=1 REQUEST_DEADLINE=7 REQUEST_KEY_ID=9
STATUS_NAMES=(None Pending Fulfilled Refunded)
get_request() { cast call --rpc-url "$RPC_URL" "$PROXY" 'getRequest(bytes32)' "$1"; }
request_status() { word_dec "$(get_request "$1")" $REQUEST_STATUS; }

# request_id_of HASH: the requestId of the RandomnessRequested log in that transaction.
request_id_of() {
  cast receipt --rpc-url "$RPC_URL" "$1" --json | jq -r --arg t "$REQUESTED_TOPIC" \
    '[.logs[] | select((.topics[0] | ascii_downcase) == $t) | .topics[1]][0] // empty'
}

active_key_id() { cast call --rpc-url "$RPC_URL" "$PROXY" 'activeKeyId()(uint32)' | cut -d' ' -f1; }
key_hash_of() { printf '0x%s' "$(word "$(cast call --rpc-url "$RPC_URL" "$PROXY" 'getProvingKey(uint32)' "$1")" 0)"; }

# need_logs_rpc: the steps that read logs need an RPC that serves eth_getLogs. Which one
# to use is not decided yet (#41), so the wizard asks for LOGS_RPC_URL and checks it with
# cast logs before the step runs.
need_logs_rpc() {
  local latest
  while :; do
    if [[ -z "${LOGS_RPC_URL:-}" ]]; then
      say "This step reads logs. The public node ($PUBLIC_RPC) does not serve eth_getLogs."
      say "Which logs-capable RPC of chain 31 to use is not decided yet: enter the one you use."
      ask_public LOGS_RPC_URL "LOGS_RPC_URL:" is_link
    fi
    note "checking that $LOGS_RPC_URL is chain 31 and serves eth_getLogs (cast logs)"
    if [[ "$(cast chain-id --rpc-url "$LOGS_RPC_URL" 2>/dev/null)" == 31 ]] &&
       latest=$(cast block-number --rpc-url "$LOGS_RPC_URL" 2>/dev/null) &&
       cast logs --rpc-url "$LOGS_RPC_URL" --from-block "$latest" --to-block "$latest" >/dev/null 2>&1; then
      printf '  %s✓%s LOGS_RPC_URL serves eth_getLogs on chain 31\n' "$GREEN" "$RESET"
      return 0
    fi
    warn "LOGS_RPC_URL ($LOGS_RPC_URL) is not chain 31, or it does not serve eth_getLogs."
    if confirm "Enter a different LOGS_RPC_URL?"; then
      LOGS_RPC_URL=""; put LOGS_RPC_URL ""
    else
      warn "This step needs logs. Stopped; rerun the wizard with a logs-capable RPC."
      exit 1
    fi
  done
}

# ── Demo scripts (run by you, in a second shell) ──────────────────────────

# demo_log_ok LOG: the script ran on chain 31, printed no FAILED line and ended with RESULT.
demo_log_ok() {
  local log="$1"
  [[ -s "$log" ]] || return 1
  grep -qE '^chain 31,' "$log" || return 1
  ! grep -qE '^FAILED' "$log" || return 1
  [[ "$(grep -vE '^[[:space:]]*$' "$log" | tail -n1)" == RESULT\ \{* ]]
}

# result_field LOG FIELD: a field of the RESULT line.
result_field() { grep -E '^RESULT \{' "$1" | tail -n1 | sed 's/^RESULT //' | jq -r --arg f "$2" '.[$f] // empty'; }

# show_demo_command NAME LOG [ENV]: the command for the second shell.
show_demo_command() {
  say "In a second shell where DEMO_PRIVATE_KEY holds a throwaway key with faucet tRBTC"
  say "(never in this shell), from the repository root:"
  printf '\n    %s%sRPC_URL="$LOGS_RPC_URL" npm run demo:%s --prefix worker 2>&1 | tee %q%s\n\n' \
    "$BOLD" "${3:+$3 }" "$1" "$2" "$RESET"
  note "LOGS_RPC_URL=$LOGS_RPC_URL. Setup is in docs/demo.md: (cd contracts && forge build), (cd worker && npm ci)."
}

# check_demo PHASE NAME: does not go on until the script's log passes.
check_demo() {
  local phase="$1" name="$2" log="$ROLLOUT_DIR/$1/demo-$2.log" extra=""
  mkdir -p "$ROLLOUT_DIR/$phase"
  if demo_log_ok "$log"; then
    printf '  %s✓%s demo:%s passed (%s)\n' "$GREEN" "$RESET" "$name" "$log"
    return 0
  fi
  if [[ "$name" == withdraw-fees ]]; then
    say "withdraw-fees: when the Payee is the Admin Safe, the script prints the Safe transaction"
    say "and exits 3. Execute it in the Safe UI, then rerun with WITHDRAW_TX=<hash> into the same file."
  fi
  while :; do
    printf '\n  %sdemo:%s%s\n' "$BOLD" "$name" "$RESET"
    show_demo_command "$name" "$log" "$extra"
    hold "Press Enter when demo:$name has finished"
    if demo_log_ok "$log"; then
      printf '  %s✓%s demo:%s passed\n' "$GREEN" "$RESET" "$name"
      return 0
    fi
    warn "demo:$name did not pass: $log has no RESULT line on chain 31, or it has a FAILED line."
    [[ -s "$log" ]] && tail -n 5 "$log" | sed 's/^/    /'
    if ! confirm "Rerun demo:$name and check again?"; then
      warn "The gate is not passed. Stopped; rerun the wizard to resume at demo:$name."
      exit 1
    fi
  done
}

# run_missed FROM TO [EXCLUDE]: runs the missed-Deadline count (it needs no key). Sets MISSED_COUNT.
run_missed() {
  local out args=("$RECORD_ABS" "$1" "$2")
  [[ -n "${3:-}" ]] && args+=(--exclude "$3")
  need_logs_rpc
  say "Running:"
  printf '    RPC_URL="$LOGS_RPC_URL" npm run demo:missed-deadlines --prefix worker -- %s\n' "${args[*]}"
  if ! out=$(RPC_URL="$LOGS_RPC_URL" npm run --silent demo:missed-deadlines --prefix "$REPO_ROOT/worker" -- "${args[@]}" 2>&1); then
    printf '%s\n' "$out" | tail -n 5 | sed 's/^/    /'
    warn "missed-deadlines failed. Fix the cause, then rerun the wizard."
    exit 1
  fi
  printf '%s\n' "$out" | grep -vE '^RESULT' | sed 's/^/    /' || true
  MISSED_COUNT=$(printf '%s\n' "$out" | grep -E '^RESULT \{' | tail -n1 | sed 's/^RESULT //' | jq -r .count)
  [[ "$MISSED_COUNT" =~ ^[0-9]+$ ]] || { warn "missed-deadlines printed no count."; exit 1; }
}

# ── Drill rows ────────────────────────────────────────────────────────────

# drill_row SEC ROW KIND "Step" "Runbook step" [instruction lines...]
# Times one row of the drill log (UTC, this machine's clock) and records its Block, Tx,
# Outcome and Runbook change. Lines that start with "$ " are commands. KIND is:
#   none         no transaction; Block is the block when the step ends
#   tx           a transaction you send from the Ledger; you paste its link
#   safe-tx      a transaction executed in the Safe UI; also asks for the Safe link
#   demo         a demo script (DEMO=<name>) that must finish and pass
#   pending      a demo script (DEMO=<name>) that leaves a request Pending; waits for its requestId
#   fulfilled    the fulfillment of the request of row FROM_ROW (read from that row's log)
#   link         a note posted in public; Outcome is its link
#   note-choice  the failover Incident Note, not decided yet: the operator decides here
drill_row() {
  local sec="$1" row="$2" kind="$3" title="$4" ref="$5" id="S${1}R${2}" line
  shift 5
  is_done "$id" && return 0
  _clear
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$SECTION_TITLE" "$RESET"
  printf '  %sRow %s: %s%s  %s(%s)%s\n\n' "$BOLD" "$row" "$title" "$RESET" "$DIM" "$ref" "$RESET"
  for line in "$@"; do
    if [[ "$line" == '$ '* ]]; then printf '    %s\n' "${line#\$ }"; else step "$line"; fi
  done
  printf '\n'
  hold "Press Enter when you START this step"
  put "${id}_START" "$(utc_time)"; put "${id}_START_AT" "$(utc_stamp)"
  local outcome="" tx="none" block=""
  case "$kind" in
    none)
      hold "Press Enter when the step is done" ;;
    tx|safe-tx)
      hold "Press Enter when the transaction is executed"
      ask_tx "${id}_HASH" "Paste the explorer link of the transaction"
      tx=$(tx_link "$(state "${id}_HASH")"); block=$(state "${id}_HASH_BLOCK")
      if [[ "$kind" == safe-tx ]]; then
        ask_public "${id}_SAFE_LINK" "Paste the Safe transaction link:" is_link
        tx+=", Safe: $(state "${id}_SAFE_LINK")"
      fi ;;
    demo|pending)
      local log="$ROLLOUT_DIR/drill/s${sec}r${row}-$DEMO.log" request_tx="" request_id="" hex
      mkdir -p "$ROLLOUT_DIR/drill"
      need_logs_rpc
      show_demo_command "$DEMO" "$log"
      while :; do
        if [[ "$kind" == pending ]]; then
          hold "Press Enter when the script prints requestId (leave it running)"
          request_id=$(grep -E '^requestId 0x[0-9a-fA-F]{64}' "$log" 2>/dev/null | tail -n1 | cut -d' ' -f2 || true)
          request_tx=$(grep -E '^request [^:]*: ' "$log" 2>/dev/null | grep -oE '0x[0-9a-fA-F]{64}' | tail -n1 || true)
          [[ -n "$request_id" && -n "$request_tx" ]] && break
          warn "$log has no request link and requestId line yet."
        else
          hold "Press Enter when the script has finished"
          if demo_log_ok "$log"; then
            request_id=$(result_field "$log" requestId); request_tx=$(result_field "$log" requestTx); break
          fi
          warn "$log has no RESULT line on chain 31, or it has a FAILED line."
          [[ -s "$log" ]] && tail -n 5 "$log" | sed 's/^/    /'
          if ! confirm "Rerun the script and check again?"; then outcome="FAILED: see $log"; break; fi
        fi
      done
      put "${id}_LOG" "$log"
      if [[ -n "$request_id" && -n "$request_tx" ]]; then
        put "${id}_REQUEST_ID" "$request_id"
        tx=$(tx_link "$request_tx"); block=$(receipt_field "$request_tx" blockNumber || true)
        put "${id}_REQUEST_BLOCK" "$block"
        hex=$(get_request "$request_id")
        put "${id}_DEADLINE" "$(word_dec "$hex" $REQUEST_DEADLINE)"
        put "${id}_KEY_ID" "$(word_dec "$hex" $REQUEST_KEY_ID)"
        say "requestId $request_id: ${STATUS_NAMES[$(word_dec "$hex" $REQUEST_STATUS)]:-?}, Deadline block $(state "${id}_DEADLINE"), keyId $(state "${id}_KEY_ID")"
      fi ;;
    fulfilled)
      local log fulfill_tx=""
      log=$(state "S${sec}R${FROM_ROW}_LOG")
      while :; do
        hold "Press Enter when the request is fulfilled (the script writing $log has finished)"
        if demo_log_ok "$log"; then fulfill_tx=$(result_field "$log" fulfillTx); break; fi
        warn "$log has no RESULT line yet, or it has a FAILED line."
        [[ -s "$log" ]] && tail -n 3 "$log" | sed 's/^/    /'
        if ! confirm "Wait and check again?"; then outcome="FAILED: see $log"; break; fi
      done
      if [[ -n "$fulfill_tx" ]]; then
        tx=$(tx_link "$fulfill_tx"); block=$(receipt_field "$fulfill_tx" blockNumber || true)
        say "Fulfiller: $(cast tx --rpc-url "$RPC_URL" "$fulfill_tx" from 2>/dev/null || echo unknown)"
        say "Blocks from the request to the fulfillment: $(blocks_between "$(state "S${sec}R${FROM_ROW}_REQUEST_BLOCK")" "$block")"
      fi ;;
    link)
      hold "Press Enter when it is posted"
      ask_public "${id}_LINK" "Paste the link to the issue:" is_link
      outcome=$(state "${id}_LINK") ;;
    note-choice)
      say "Whether a failover drill gets an Incident Note is not decided yet. You decide it here."
      if confirm "Post an Incident Note for this failover drill (outage.md 1.5)?"; then
        put S1_INCIDENT_NOTE yes
        hold "Press Enter when it is posted"
        ask_public "${id}_LINK" "Paste the link to the issue:" is_link
        outcome=$(state "${id}_LINK")
      else
        put S1_INCIDENT_NOTE no
        outcome="no Incident Note: the operator chose not to post one"
      fi ;;
  esac
  [[ -n "$block" ]] || block=$(block_now)
  put "${id}_END" "$(utc_time)"; put "${id}_END_AT" "$(utc_stamp)"
  put "${id}_BLOCK" "$block"
  put "${id}_TX" "$tx"
  if [[ -z "$outcome" ]]; then
    ask_default "${id}_OUTCOME" "What did the Verify line show?" ok
  else
    put "${id}_OUTCOME" "$outcome"
  fi
  ask_default "${id}_CHANGE" "Runbook change you made for this step?" none
  put "DONE_${id}" "$(utc_stamp)"
}

# ── Stages ────────────────────────────────────────────────────────────────

stage_rpc() {
  say "Rootstock testnet is chain 31. The checks and the Safe reads use this RPC."
  say "The public node does not serve eth_getLogs; the steps that need logs ask for LOGS_RPC_URL."
  while :; do
    ask_default RPC_URL "RPC_URL:" "$PUBLIC_RPC"
    [[ "$(cast chain-id --rpc-url "$RPC_URL" 2>/dev/null)" == 31 ]] && break
    warn "$RPC_URL is not chain 31."
    RPC_URL=""; put RPC_URL ""
  done
  printf '  %s✓%s cast chain-id prints 31\n' "$GREEN" "$RESET"
}

stage_safe() {
  say "The Admin Safe is a SafeL2 v1.4.1, 2-of-3. Each owner is a hardware wallet, and the"
  say "three owners are held by at least two people. (deploy.md, section 1)"
  open_url "$SAFE_UI"
  step "Select Rootstock Testnet. Connect one of the owner wallets."
  step "Create a new Safe: add the three owner addresses, and set the threshold to 2."
  step "Pay for the creation with faucet tRBTC. Write the Safe address in your own records."
  ask_public SAFE "Admin Safe address:" is_address
  local version slot threshold owners
  version=$(cast call --rpc-url "$RPC_URL" "$SAFE" 'VERSION()(string)' | tr -d '"')
  slot=$(cast storage --rpc-url "$RPC_URL" "$SAFE" 0 | tr '[:upper:]' '[:lower:]')
  threshold=$(cast call --rpc-url "$RPC_URL" "$SAFE" 'getThreshold()(uint256)' | cut -d' ' -f1)
  owners=$(cast call --rpc-url "$RPC_URL" "$SAFE" 'getOwners()(address[])' | grep -oE '0x[0-9a-fA-F]{40}' | wc -l | tr -d ' ')
  say "VERSION $version, singleton $slot, threshold $threshold, $owners owners"
  if [[ "$version" != 1.4.1 || "$slot" != "$SAFE_L2_SINGLETON" || "$threshold" != 2 || "$owners" != 3 ]]; then
    warn "This is not a SafeL2 v1.4.1 2-of-3. Do not use it. Create a new Safe, then rerun."
    put SAFE ""
    exit 1
  fi
  printf '  %s✓%s SafeL2 v1.4.1, 2-of-3\n' "$GREEN" "$RESET"
}

stage_deploy() {
  say "deploy.sh refuses to run on chain 31 from a tree with uncommitted changes."
  while [[ -n "$(git -C "$REPO_ROOT" status --porcelain)" ]]; do
    warn "The working tree has uncommitted changes."
    hold "Commit or remove them, then press Enter"
  done
  say "The Proving Key's public point, from the keygen output (it is public):"
  ask_point PROVING_KEY "the Proving Key"
  say "From the repository root, in your shell, signing with the Ledger:"
  printf '\n    contracts/script/deploy.sh %s %s %s --ledger\n\n' "$SAFE" "$PROVING_KEY_X" "$PROVING_KEY_Y"
  note "Any forge wallet flag works in place of --ledger (for example --account deployer)."
  note "Never pass --private-key. The script deploys, registers the key, sets the config,"
  note "offers the Admin role to the Admin Safe and writes $RECORD."
  while :; do
    hold "Press Enter when deploy.sh has finished"
    if [[ -f "$RECORD_ABS" ]] && [[ "$(jq -r .safe "$RECORD_ABS" | tr '[:upper:]' '[:lower:]')" == "$(printf '%s' "$SAFE" | tr '[:upper:]' '[:lower:]')" ]]; then
      break
    fi
    warn "$RECORD is missing, or its safe is not $SAFE."
  done
  put PROXY "$(jq -r .contracts.proxy.address "$RECORD_ABS")"
  put DEPLOY_BLOCK "$(jq -r .contracts.proxy.block "$RECORD_ABS")"
  say "Coordinator proxy: $PROXY, from block $DEPLOY_BLOCK"
}

stage_verify() {
  local c v missing
  while :; do
    missing=""
    for c in implementation proxy; do for v in blockscout sourcify; do
      [[ -n "$(jq -r --arg c "$c" --arg v "$v" '.contracts[$c].verification[$v] // empty' "$RECORD_ABS")" ]] || missing+=" $c/$v"
    done; done
    [[ -z "$missing" ]] && break
    warn "Not verified yet:$missing"
    say "Rerun the verifier once the explorer is back:"
    printf '\n    contracts/script/verify.sh %s\n\n' "$RECORD"
    hold "Press Enter when verify.sh has finished"
  done
  printf '  %s✓%s implementation and proxy verified on Blockscout and Sourcify\n' "$GREEN" "$RESET"
  open_url "$EXPLORER/address/$PROXY?tab=contract"
  step "Check that Blockscout shows the proxy as a proxy, with the coordinator's read and write tabs."
  if ! confirm "Does Blockscout link the proxy to the implementation?"; then
    warn "Do not continue until Blockscout links the proxy to the implementation. Rerun then."
    exit 1
  fi
}

stage_handoff() {
  say "The hand-off transaction (safe-tx.sh calls it from the Admin Safe first; it signs nothing):"
  printf '\n    contracts/script/safe-tx.sh %s accept-ownership\n\n' "$RECORD"
  if ! RPC_URL="$RPC_URL" "$REPO_ROOT/contracts/script/safe-tx.sh" "$RECORD_ABS" accept-ownership | sed 's/^/    /'; then
    warn "safe-tx.sh printed no transaction. Read the reason above."
    exit 1
  fi
  open_url "$SAFE_UI"
  step "Open the Admin Safe, then New transaction, then Transaction Builder."
  step "Enter the to address, value 0, and the data as custom data."
  step "Each signer compares to and data with the output above before signing. Execute it."
  hold "Press Enter when the transaction is executed"
  ask_tx HANDOFF_TX "Paste the explorer link of the executed transaction"
  ask_public HANDOFF_SAFE_LINK "Paste the Safe transaction link:" is_link
}

stage_check() {
  say "The check takes the Admin Safe from your records ($SAFE), not from the record:"
  printf '\n    (cd contracts && forge script script/CheckDeployment.s.sol:CheckDeployment --rpc-url "$RPC_URL" \\\n'
  printf '      --sig "run(string,address)" ../%s "$SAFE")\n\n' "$RECORD"
  until (cd "$REPO_ROOT/contracts" && forge script script/CheckDeployment.s.sol:CheckDeployment --rpc-url "$RPC_URL" \
          --sig "run(string,address)" "$RECORD_ABS" "$SAFE" 2>&1 | tail -n 5 | sed 's/^/    /'; exit "${PIPESTATUS[0]}"); do
    warn "The check failed. Mismatch(\"<field>\") names the first value that differs."
    confirm "Check again?" || exit 1
  done
  printf '  %s✓%s CheckDeployment passed\n' "$GREEN" "$RESET"
}

stage_discard() {
  say "The check passed and Blockscout shows the proxy. Until now the deployer key could redo"
  say "the deploy. Discard it now, by hand. The wizard never sees it."
  if ! confirm "Have you discarded the deployer key? This cannot be undone."; then
    warn "Rerun the wizard when the deployer key is discarded."
    exit 1
  fi
}

stage_commit() {
  say "Commit the deployment record:"
  printf '\n    git add %s && git commit -m "deploy: chain 31 coordinator"\n\n' "$RECORD"
  while :; do
    hold "Press Enter when it is committed"
    if git -C "$REPO_ROOT" ls-files --error-unmatch "$RECORD_ABS" >/dev/null 2>&1 &&
       git -C "$REPO_ROOT" diff --quiet HEAD -- "$RECORD_ABS"; then
      break
    fi
    warn "$RECORD is not committed, or it has changes after the commit."
  done
  put RECORD_COMMIT "$(git -C "$REPO_ROOT" log -1 --format=%h -- "$RECORD_ABS")"
}

stage_gate() {
  say "Gate (#41 step 2): every demo script passes its assertions on chain 31 before the drill."
  say "Each script writes its output to a file in $ROLLOUT_DIR/gate; the wizard reads it. (docs/demo.md)"
  need_logs_rpc
  local name
  for name in "${DEMO_SCRIPTS[@]}"; do check_demo gate "$name"; done
  printf '\n  %s✓%s gate passed: all %s demo scripts\n' "$GREEN" "$RESET" "${#DEMO_SCRIPTS[@]}"
}

stage_drill_header() {
  say "Testnet pilot; the coordinator is not externally audited."
  say "The drill: failover, then a Rotation with a request pending, then a Revocation with a"
  say "request pending and its refund. The wizard times each row in UTC from this machine's clock."
  put DL_DATE "$(date -u +%Y-%m-%d)"
  ask_public DL_OPERATOR "Operator (your name):" is_text
  ask_public DL_SIGNERS "Admin Safe signers of the drill (two names, comma separated):" is_text
  put DL_COMMIT "${RECORD_COMMIT:-$(git -C "$REPO_ROOT" log -1 --format=%h -- "$RECORD_ABS")}"
  local id; id=$(active_key_id)
  put KEY_BEFORE_ID "$id"; put KEY_BEFORE_HASH "$(key_hash_of "$id")"
  put DL_KEY_BEFORE "$KEY_BEFORE_ID, keyHash $KEY_BEFORE_HASH"
  say "Active Key before the drill: $DL_KEY_BEFORE"
  step "Announce the drill in the Warn channel."
  ask_public DL_ANNOUNCEMENT "Link to the announcement:" is_link
  put DRILL_FROM_BLOCK "$(block_now)"
}

SSM='aws ssm send-command --region eu-central-1 --instance-ids <instance_id> --document-name AWS-RunShellScript'

stage_failover() {
  SECTION_TITLE="Drill 1: failover to the Backup Worker (outage.md 8.1)"
  drill_row 1 1 none "Announce the drill" "outage.md 8.1.1" \
    "Post in the Warn channel:" '$ Failover drill starts now. The primary worker stops. Expect a healthchecks.io Page for primary.'
  drill_row 1 2 none "Stop only the Primary Worker" "outage.md 8.1.2" \
    "With the host-access role:" "\$ $SSM --parameters 'commands=[\"cd /opt/rsk-vrf && docker compose --env-file host.env --env-file worker-image.env stop worker\"]'" \
    "Do not use systemctl stop rsk-vrf: it stops rskj too." \
    "Verify: aws logs tail /rsk-vrf/primary --region eu-central-1 --since 5m --filter-pattern poll_result shows no new lines."
  drill_row 1 3 none "Heartbeat Page for primary (expected)" "outage.md 8" \
    "After about 5 minutes the primary check in healthchecks.io Pages. Acknowledge it. Do not do section 1."
  DEMO=dice drill_row 1 4 pending "Make the request" "outage.md 8.1.3, demo.md dice" \
    "The Backup Worker must fulfill it after GRACE_BLOCKS ($GRACE_BLOCKS). Leave the script running."
  FROM_ROW=4 drill_row 1 5 fulfilled "Backup Worker fulfills the request" "outage.md 8.1.3" \
    "Verify: the Fulfiller is the Fulfiller address of backup, at least $GRACE_BLOCKS blocks after the request."
  drill_row 1 6 none "Restart the Primary Worker" "outage.md 8.1.4" \
    "\$ $SSM --parameters 'commands=[\"systemctl restart rsk-vrf\"]'" "Verify: as in outage.md section 1, step 3."
  drill_row 1 7 note-choice "Post the Incident Note" "outage.md 1.5"
  put S1_REQUEST_ID "$(state S1R4_REQUEST_ID)"; put S1_DEADLINE "$(state S1R4_DEADLINE)"
  put S1_BLOCKS "$(blocks_between "$(state S1R4_BLOCK)" "$(state S1R5_BLOCK)")"
}

stage_rotation() {
  SECTION_TITLE="Drill 2: Rotation with a request pending (rotation.md)"
  need_logs_rpc
  drill_row 2 1 none "Announce the Rotation" "rotation.md 1" "Post the text of rotation.md step 1 in the Warn channel."
  drill_row 2 2 none "Generate the new Proving Key" "rotation.md 2" \
    "On the Admin's machine, on an encrypted disk, as in rotation.md step 2." \
    "The secret stays in its file. The wizard asks only for the public point."
  drill_row 2 3 none "Write the secret and the offline backups" "rotation.md 3" "As in rotation.md step 3."
  drill_row 2 4 none "check-key on both hosts" "rotation.md 4" \
    "On each host: sudo docker compose --env-file host.env --env-file worker-image.env run --rm --no-deps worker src/main.ts check-key <NEW>" \
    "Do not go on until both hosts pass."
  DEMO=read-path drill_row 2 5 pending "Make the pending request" "demo.md read-path" \
    "Make it before the Admin Safe registers the new key, and leave the script running."
  if ! is_done S2R6; then
    say "The new Proving Key's public point (public):"
    ask_point NEW_KEY "the new Proving Key"
    [[ "$(request_status "$(state S2R5_REQUEST_ID)")" == 1 ]] ||
      warn "The pending request is no longer Pending. The drill needs it Pending when the Safe registers the new key."
  fi
  drill_row 2 6 safe-tx "Register the new key from the Admin Safe" "rotation.md 5" \
    "\$ contracts/script/safe-tx.sh $RECORD register $(state NEW_KEY_X) $(state NEW_KEY_Y)" \
    "Make sure the keyHash in the summary is the new keyHash. Each signer compares to and data before signing."
  if [[ -z "$(state S2_NEW_KEY_ID)" ]]; then
    local id; id=$(active_key_id)
    put S2_NEW_KEY_ID "$id"; put S2_NEW_KEY_HASH "$(key_hash_of "$id")"; put S2_NEW_KEY_BLOCK "$(state S2R6_BLOCK)"
  fi
  drill_row 2 7 none "Both workers hold both keys" "rotation.md 6.1" \
    "aws logs tail /rsk-vrf/<host> ... --filter-pattern key_sync on both hosts: both keyHashes held:true."
  DEMO=dice drill_row 2 8 demo "Test request under the new keyHash" "rotation.md 6.2" \
    "Verify: the request is Fulfilled and its keyId is $(state S2_NEW_KEY_ID)."
  FROM_ROW=5 drill_row 2 9 fulfilled "The pending request is Fulfilled with the old key" "rotation.md 6.3"
  local retire=$(( $(state S2_NEW_KEY_BLOCK) + RETIRE_BLOCKS ))
  drill_row 2 10 none "Delete the online secret of the Retired key" "rotation.md 7" \
    "The old key is Retired $RETIRE_BLOCKS blocks after the Rotation, at block $retire (now $(block_now))." \
    "You can stop the wizard (Ctrl-C) now and rerun it then: it resumes at this row." \
    "\$ RPC_URL=\"\$LOGS_RPC_URL\" contracts/script/pending-requests.sh $RECORD $(state KEY_BEFORE_HASH)" \
    "Verify: the key is Retired with 0 Pending. Then rotation.md 7.2: remove the old keyHash from infra/terraform.tfvars, plan and apply."
  drill_row 2 11 link "Post the public note" "rotation.md 8" "gh issue create with the Rotation note template, then close it. No incident label."
  put S2_REQUEST_ID "$(state S2R5_REQUEST_ID)"; put S2_OLD_KEY_ID "$(state S2R5_KEY_ID)"; put S2_DEADLINE "$(state S2R5_DEADLINE)"
}

stage_revocation() {
  SECTION_TITLE="Drill 3: Revocation with a request pending and its refund (compromise.md 1)"
  need_logs_rpc
  DEMO=read-path drill_row 3 1 pending "Make the pending request" "demo.md read-path" \
    "Make it under the key that the drill revokes, and leave the script running."
  [[ -n "$(state S3_REVOKED_HASH)" ]] || put S3_REVOKED_HASH "$(key_hash_of "$(state S3R1_KEY_ID)")"
  drill_row 3 2 safe-tx "Revoke the key from the Admin Safe" "compromise.md 1.1" \
    "\$ contracts/script/safe-tx.sh $RECORD revoke $(state S3_REVOKED_HASH)" \
    "Each signer compares to and data before signing. Execute it."
  drill_row 3 3 none "key_registry_changed Page from both workers" "compromise.md 1.1" "Both workers Page for KeyStateChanged."
  if ! is_done S3R4; then
    say "The public point of the next Proving Key (rotation.md steps 2 to 4 first):"
    ask_point NEXT_KEY "the next Proving Key"
  fi
  drill_row 3 4 safe-tx "Rotation to a new Active Key" "compromise.md 1.2" \
    "Do rotation.md steps 2 to 4, then:" "\$ contracts/script/safe-tx.sh $RECORD register $(state NEXT_KEY_X) $(state NEXT_KEY_Y)"
  [[ -n "$(state S3_NEW_KEY_ID)" ]] || put S3_NEW_KEY_ID "$(active_key_id)"
  drill_row 3 5 tx "Refund the pending request (timeoutRefund, reason KeyRevoked)" "compromise.md 1.3" \
    "From the Operator Funding Wallet, on the Ledger:" \
    "\$ cast send --rpc-url \"\$RPC_URL\" --ledger $PROXY 'timeoutRefund(bytes32)' $(state S3R1_REQUEST_ID)"
  drill_row 3 6 none "Delete the secret of the Revoked key" "compromise.md 1.4.1" "In both regions, as in compromise.md 1.4.1."
  drill_row 3 7 none "CloudTrail review" "compromise.md 1.4.2" "As in compromise.md 1.4.2."
  drill_row 3 8 link "Post the Incident Note" "compromise.md 1.5" "gh issue create --label incident with the Revocation template."
  put S3_REQUEST_ID "$(state S3R1_REQUEST_ID)"; put S3_KEY_ID "$(state S3R1_KEY_ID)"; put S3_DEADLINE "$(state S3R1_DEADLINE)"
  put S3_BLOCKS "$(blocks_between "$(state S3R2_BLOCK)" "$(state S3R5_BLOCK)")"
  if [[ -z "$(state S3_MISSED)" ]]; then
    run_missed "$(state DRILL_FROM_BLOCK)" "$(block_now)"
    put S3_MISSED "$MISSED_COUNT"
  fi
}

# outage_begin N "Step" / outage_end N: time one step of outage.md 8.2.
outage_begin() { put "OUT${1}_TITLE" "$2"; put "OUT${1}_START" "$(utc_time)"; put "OUT${1}_START_AT" "$(utc_stamp)"; }
outage_end()   { put "OUT${1}_END" "$(utc_time)"; put "OUT${1}_END_AT" "$(utc_stamp)"; put "OUT${1}_BLOCK" "$(block_now)"; put "DONE_OUT$1" "$(utc_stamp)"; }

stage_outage() {
  say "outage.md 8.2: both workers stop for at least 1,250 blocks, announced at least 24 hours before."
  local now announced
  if ! is_done OUT1; then
    outage_begin 1 "Announce the window"
    printf '    gh issue create --repo mangekyou-labs/rsk-vrf --title "Planned outage window: <date, UTC>" --body ...\n'
    ask_public OUT_ANNOUNCEMENT "Link to the announcement issue:" is_link
    put OUT_ANNOUNCED_EPOCH "$(date -u +%s)"
    outage_end 1
  fi
  now=$(date -u +%s); announced=$(state OUT_ANNOUNCED_EPOCH)
  if (( now - announced < 86400 )); then
    warn "The window was announced less than 24 hours ago. Rerun the wizard after $(date -u -r $((announced + 86400)) +%Y-%m-%dT%H:%MZ 2>/dev/null || date -u -d "@$((announced + 86400))" +%Y-%m-%dT%H:%MZ)."
    exit 1
  fi
  if ! is_done OUT2; then
    outage_begin 2 "Only demo requests are Pending"
    need_logs_rpc
    say "Pending requests of the Active Key:"
    RPC_URL="$LOGS_RPC_URL" "$REPO_ROOT/contracts/script/pending-requests.sh" "$RECORD_ABS" "$(key_hash_of "$(active_key_id)")" 2>&1 | sed 's/^/    /' || true
    confirm "Is each listed request from the demo key (or is the list empty)?" || { warn "Wait until the other requests are fulfilled, then rerun."; exit 1; }
    outage_end 2
  fi
  if ! is_done OUT3; then
    outage_begin 3 "Stop the worker on both hosts"
    step "Stop the worker on primary (eu-central-1) and backup (us-east-1), as in outage.md 8."
    step "Post in the Warn channel: Outage window starts now. Expect healthchecks.io Pages for both hosts."
    hold "Press Enter when both checks in healthchecks.io are down"
    outage_end 3
    put OUT_WINDOW_FROM "$(state OUT3_BLOCK)"
  fi
  if ! is_done OUT4; then
    outage_begin 4 "Make the demo request"
    say "In the second shell (the throwaway key), as in outage.md 8.2 step 4:"
    printf '    TAG=$(cast format-bytes32-string outage-window)\n'
    printf '    cast send --rpc-url "$RPC_URL" --private-key "$DEMO_PRIVATE_KEY" %s '\''request(bytes32)'\'' "$TAG" --value "$FEE"\n' "$PROXY"
    ask_tx OUT_REQUEST_TX "Paste the explorer link of the request transaction"
    put OUT_REQUEST_ID "$(request_id_of "$(state OUT_REQUEST_TX)")"
    [[ -n "$(state OUT_REQUEST_ID)" ]] || { warn "That transaction made no request on $PROXY."; put OUT_REQUEST_TX ""; exit 1; }
    put OUT_DEADLINE "$(word_dec "$(get_request "$(state OUT_REQUEST_ID)")" $REQUEST_DEADLINE)"
    say "requestId $(state OUT_REQUEST_ID), Deadline block $(state OUT_DEADLINE)"
    outage_end 4
  fi
  if ! is_done OUT5; then
    outage_begin 5 "Wait until the block is past the Deadline"
    until (( $(block_now) > $(state OUT_DEADLINE) )); do
      say "Block $(block_now), Deadline $(state OUT_DEADLINE). You can stop (Ctrl-C) and rerun later."
      hold "Press Enter to check again"
    done
    outage_end 5
  fi
  if ! is_done OUT6; then
    outage_begin 6 "Refund the request"
    printf '    cast send --rpc-url "$RPC_URL" --private-key "$DEMO_PRIVATE_KEY" %s '\''timeoutRefund(bytes32)'\'' %s\n' "$PROXY" "$(state OUT_REQUEST_ID)"
    ask_tx OUT_REFUND_TX "Paste the explorer link of the refund transaction"
    [[ "$(request_status "$(state OUT_REQUEST_ID)")" == 3 ]] || warn "getRequest does not show Refunded (3)."
    outage_end 6
  fi
  if ! is_done OUT7; then
    outage_begin 7 "Start the worker on both hosts again"
    step "systemctl restart rsk-vrf on both hosts, not more than 2,400 blocks after the request (block $(( $(state OUT_REQUEST_TX_BLOCK) + 2400 )); now $(block_now))."
    step "Verify: both checks are up, and each worker Pages missed_deadline for $(state OUT_REQUEST_ID) with a proof that is not null."
    hold "Press Enter when both workers run again"
    outage_end 7
    put OUT_WINDOW_TO "$(state OUT7_BLOCK)"
  fi
  if ! is_done OUT8; then
    outage_begin 8 "Post the Incident Note (outage.md 5)"
    step "Do outage.md section 5 for the request. The cause is the planned outage window; link the announcement."
    ask_public OUT_NOTE "Link to the Incident Note:" is_link
    step "Close the announcement issue with a link to the note."
    outage_end 8
  fi
}

stage_missed() {
  say "outage.md section 7: the missed-Deadline count. The target is 0 outside the announced window."
  local from to
  from=$(jq -r .contracts.proxy.block "$RECORD_ABS")
  to=$(block_now)
  run_missed "$from" "$to" "$(state OUT_WINDOW_FROM)-$(state OUT_WINDOW_TO)"
  put MISSED_FROM "$from"; put MISSED_TO "$to"; put MISSED_COUNT "$MISSED_COUNT"
  if [[ "$MISSED_COUNT" != 0 ]]; then
    warn "$MISSED_COUNT missed Deadline(s) outside the window. Each needs an Incident Note (outage.md section 5)."
  else
    printf '  %s✓%s 0 missed Deadlines outside the window\n' "$GREEN" "$RESET"
  fi
  hold
}

stage_final() {
  say "The final demo run, against the Active Key after the drill Rotation. (docs/demo.md)"
  local active name; active=$(active_key_id)
  if [[ "$active" != "$(state S3_NEW_KEY_ID)" ]]; then
    warn "The Active Key is $active, not $(state S3_NEW_KEY_ID), the key of the drill Rotation. Stopped."
    exit 1
  fi
  need_logs_rpc
  for name in "${DEMO_SCRIPTS[@]}"; do check_demo final "$name"; done
  say "Fill in the Results section of docs/demo.md from these logs in $ROLLOUT_DIR/final:"
  for name in "${DEMO_SCRIPTS[@]}"; do note "  demo-$name.log: $(grep -E '^RESULT' "$ROLLOUT_DIR/final/demo-$name.log" | tail -n1)"; done
  hold
}

stage_publish() {
  ask_default SUM_PR "Link to the PR with the runbook changes of the drill?" none
  python3 "$REPO_ROOT/contracts/script/rollout-drill-log.py" "$REPO_ROOT/docs/runbooks/drill-log.md" "$ENV_FILE" > "$DRILL_LOG"
  printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$DRILL_LOG"
  say "Publish it with the runbook changes, for example:"
  printf '    gh issue create --repo mangekyou-labs/rsk-vrf --title "Drill log: chain 31" --body-file %q\n' "$DRILL_LOG"
}

run_wizard() {

refuse_key_env
TOTAL_STAGES=${#STEP_IDS[@]}
mkdir -p "$ROLLOUT_DIR"
chmod 700 "$ROLLOUT_DIR"
cd "$REPO_ROOT"
if [[ "$RECORD" == /* ]]; then RECORD_ABS="$RECORD"; else RECORD_ABS="$REPO_ROOT/$RECORD"; fi
load_state

if [[ "${1:-}" == --status ]]; then print_status; return 0; fi
[[ $# -eq 0 ]] || { echo "Usage: contracts/script/rollout-wizard.sh [--status]" >&2; exit 2; }

banner "Chain 31 rollout (#41 steps 1 to 5)"
note "state: $ENV_FILE (rerun to resume). Testnet pilot, not externally audited."
note "This wizard never asks for a key: signing stays on the Ledger and in the Safe UI."

run_step rpc stage_rpc
run_step safe stage_safe
run_step deploy stage_deploy
run_step verify stage_verify
run_step handoff stage_handoff
run_step check stage_check
run_step discard stage_discard
run_step commit stage_commit
run_step gate stage_gate
run_step drill-header stage_drill_header
run_step failover stage_failover
run_step rotation stage_rotation
run_step revocation stage_revocation
run_step outage stage_outage
run_step missed stage_missed
run_step final stage_final
run_step publish stage_publish

finish
}

run_wizard "$@"; exit

